public fun zLivelinessDeclareSubscriber(
    session: ZSession,
    keyExprSel: Int,
    keyExpr0: String?,
    keyExpr1: ZKeyExpr?,
    history: Boolean,
    callback: (
        keyExpr: ZKeyExpr,
        keyExprAsStr: String,
        payloadToBytes: ByteArray,
        encodingToString: String,
        kind: Int,
        timestampNtp64: Long?,
        express: Boolean,
        priority: Int,
        congestionControl: Int,
        attachmentToBytes: ByteArray?,
        reliability: Int,
        sourceZid: ZZenohId?,
        sourceEid: Int,
        sourceSn: Long,
    ) -> Unit,
    onClose: () -> Unit,
    onError: (je: String?, message: String) -> ZSubscriber,
): ZSubscriber {
    if (session.ptr == 0L) return onError("Operation on a closed native handle.", "")
    if (keyExpr1 != null && keyExpr1.ptr == 0L) return onError(
        "Operation on a closed native handle.",
        "",
    )
    var __cap_failed = false
    var __cap_je: String? = null
    var __cap_ze0: String? = null
    val __cap = {
        __je: String?,
        __ze0: String?,
        ->
        __cap_failed = true; __cap_je = __je; __cap_ze0 = __ze0
    }
    val __ret = run {
        val __locks = ArrayList<NativeHandle>()
        __locks.add(session)
        keyExpr1?.let { __locks.add(it) }
        withSortedHandleLocks(__locks) {
            val session_ptr = session.ptr
            val keyExpr1_ptr = keyExpr1?.ptr ?: 0L
            try {
                ZSubscriber(
                    JNINative.zLivelinessDeclareSubscriber(
                        session_ptr,
                        keyExprSel,
                        keyExpr0,
                        keyExpr1_ptr,
                        history,
                        {
                            keyExpr: ZKeyExpr,
                            keyExprAsStr: String,
                            payloadToBytes: ByteArray,
                            encodingToString: String,
                            kind: Int,
                            timestampNtp64: Long?,
                            express: Boolean,
                            priority: Int,
                            congestionControl: Int,
                            attachmentToBytes: ByteArray?,
                            reliability: Int,
                            sourceZid: ByteArray?,
                            sourceEid: Int,
                            sourceSn: Long,
                            ->
                            callback(
                                keyExpr,
                                keyExprAsStr,
                                payloadToBytes,
                                encodingToString,
                                kind,
                                timestampNtp64,
                                express,
                                priority,
                                congestionControl,
                                attachmentToBytes,
                                reliability,
                                sourceZid?.let { ZZenohId(it) },
                                sourceEid,
                                sourceSn,
                            )
                        },
                        onClose,
                        __cap,
                    ),
                )
            } finally {
                keyExpr1?.let { it.ptr = 0L }
            }
        }
    }
    if (__cap_failed) return onError(__cap_je, (__cap_ze0 ?: ""))
    return __ret
}
